'use strict';

// MODULES //

var isArray = require( '@stdlib/assert-is-array' );
var isPlainObject = require( '@stdlib/assert-is-plain-object' );
var hasOwnProp = require( '@stdlib/assert-has-own-property' );
var format = require( '@stdlib/string-format' );
var parse = require( '@stdlib/utils-json-pointer-parse' );
var isSafeToken = require( '@stdlib/utils-json-pointer-base-assert-is-safe-token' );
var resolveToken = require( '@stdlib/utils-json-pointer-base-resolve-token' );


// MAIN //

/**
* Resolves a JSON Pointer against a document and returns the target, key, and value.
*
* ## Notes
*
* -   Implements resolution per RFC 6901.
* -   An empty string pointer refers to the root of the document.
* -   The `-` token on the last segment of a pointer targeting an array resolves to the array's length (i.e., past-the-end index).
* -   Tokens `__proto__`, `constructor`, and `prototype` are rejected to prevent prototype pollution.
*
* @param {(Object|Array)} document - JSON document
* @param {string} pointer - JSON Pointer string
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a string
* @throws {Error} pointer must resolve to an existing location in the document
* @throws {Error} tokens must not be prototype pollution vectors
* @throws {RangeError} array index must be within bounds
* @returns {Object} result object
*
* @example
* var out = resolve( { 'foo': [ 'bar', 'baz' ] }, '/foo/0' );
* // returns { 'target': [ 'bar', 'baz' ], 'key': 0, 'value': 'bar' }
*
* @example
* var out = resolve( { 'foo': 'bar' }, '/foo' );
* // returns { 'target': { 'foo': 'bar' }, 'key': 'foo', 'value': 'bar' }
*
* @example
* var out = resolve( { 'foo': 'bar' }, '' );
* // returns { 'target': null, 'key': null, 'value': { 'foo': 'bar' } }
*/
function resolve( document, pointer ) {
	var current;
	var tokens;
	var token;
	var last;
	var key;
	var idx;
	var i;

	if ( !isPlainObject( document ) && !isArray( document ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an object or an array. Value: `%s`.', document ) );
	}
	tokens = parse( pointer );

	// An empty pointer refers to the root:
	if ( tokens.length === 0 ) {
		return {
			'target': null,
			'key': null,
			'value': document
		};
	}

	current = document;
	last = tokens.length - 1;

	// Traverse all tokens except the last to find the target:
	for ( i = 0; i < last; i++ ) {
		token = tokens[ i ];
		if ( !isSafeToken( token ) ) {
			throw new Error( format( 'invalid argument. Pointer contains an unsafe token. Value: `%s`.', token ) );
		}
		if ( isArray( current ) ) {
			idx = resolveToken( current, token );
			if ( idx >= current.length ) {
				throw new RangeError( format( 'invalid argument. Array index out of bounds. Index: `%d`. Length: `%d`.', idx, current.length ) );
			}
			current = current[ idx ];
		} else if ( isPlainObject( current ) ) {
			if ( !hasOwnProp( current, token ) ) {
				throw new Error( format( 'invalid argument. Pointer references a nonexistent property. Value: `%s`.', token ) );
			}
			current = current[ token ];
		} else {
			throw new TypeError( format( 'invalid argument. Pointer references a non-traversable value. Value: `%s`.', token ) );
		}
	}

	// Handle the last token to determine the final key and value:
	token = tokens[ last ];
	if ( !isSafeToken( token ) ) {
		throw new Error( format( 'invalid argument. Pointer contains an unsafe token. Value: `%s`.', token ) );
	}
	if ( isArray( current ) ) {
		key = resolveToken( current, token );
		if ( token !== '-' && key >= current.length ) {
			throw new RangeError( format( 'invalid argument. Array index out of bounds. Index: `%d`. Length: `%d`.', key, current.length ) );
		}
	} else if ( isPlainObject( current ) ) {
		if ( !hasOwnProp( current, token ) ) {
			throw new Error( format( 'invalid argument. Pointer references a nonexistent property. Value: `%s`.', token ) );
		}
		key = token;
	} else {
		throw new TypeError( format( 'invalid argument. Pointer references a non-traversable value. Value: `%s`.', token ) );
	}
	return {
		'target': current,
		'key': key,
		'value': current[ key ]
	};
}


// EXPORTS //

module.exports = resolve;
